mpty\n        kind: steps\n        steps:\n          - Perform the example action with empty input.\n          - Observe the documented empty-input behaviour.\n    # What a person can see when the behaviour holds \u2014 the acceptance criteria.\n    observable_outcomes:\n      - The expected result is visible to the user.\n      - Invalid input is refused with a clear message.\n    host_applicability:\n      - host_surface: codex.cli\n        supported: true\n    # Which verifier (from use-cases.yml) has to pass for this row to count.\n    verification_policy:\n      mode: requirements\n      requirements:\n        - evidence_kind: test_result\n          required_verifiers: [acceptance]\n          minimum_count: 1\n    # Whether a human must sign this row off in a showcase before release.\n    approval_policy:\n      mode: none\n"},{"path":"outside","kind":"directory"}],"hooks_path_after":null},{"name":"init_force_after_separator","args":["init","--repo","$SANDBOX","--json","--","--force"],"setup":{"git":false,"hooks_path":null,"repository":true,"directories":[],"files":[{"path":"demo-repo/use-cases.yml","content":"schema_version: 1\n"}],"symlinks":[]},"stdout":"{\"schema_version\":1,\"protocol_version\":1,\"command\":\"init\",\"ok\":true,\"complete\":true,\"data\":{\"schema_version\":1,\"status\":\"created\",\"template\":\"generic\",\"component_id\":\"demo-repo\",\"default_verifier\":{\"id\":\"acceptance\",\"kind\":\"script\",\"command\":[\"false\",\"TODO-replace-with-your-verifier-command-for-{slug}\"]},\"created_files\":[\"use-cases.yml\",\"use-cases/example.yml\",\".gitignore\",\"AGENTS.md\",\".githooks/pre-commit\",\".githooks/pre-push\"],\"agents_md\":{\"status\":\"created\",\"decision\":\"yes\"},\"git_hooks\":{\"hooks_dir\":\".githooks\",\"hooks_path_set\":false,\"extended\":[]},\"next_steps\":[\"Point git at the hooks once the repo is initialised: `git config core.hooksPath .githooks`.\",\"Copy use-cases/example.yml's row for your first real use case, then d